create table if not exists public.reply_quotes (id uuid primary key default gen_random_uuid(),reply_id uuid not null references public.replies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,content text not null default '',created_at timestamptz not null default now(),unique(reply_id,user_id));
create index if not exists reply_quotes_reply_idx on public.reply_quotes(reply_id);
alter table public.reply_quotes enable row level security;
drop policy if exists reply_quotes_read on public.reply_quotes;
create policy reply_quotes_read on public.reply_quotes for select using (true);
drop policy if exists reply_quotes_owner_write on public.reply_quotes;
create policy reply_quotes_owner_write on public.reply_quotes for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
create or replace function public.testagram_toggle_reply_reaction(p_reply_id uuid,p_emoji text) returns jsonb language plpgsql security invoker set search_path=public as $$ declare u uuid:=auth.uid(); a boolean; n bigint; begin if u is null then raise exception using errcode='42501',message='Authentication required'; end if; if nullif(trim(p_emoji),'') is null then raise exception using errcode='22023',message='Reaction emoji is required'; end if; select exists(select 1 from reply_reactions where reply_id=p_reply_id and user_id=u and emoji=p_emoji) into a; if a then delete from reply_reactions where reply_id=p_reply_id and user_id=u and emoji=p_emoji; else insert into reply_reactions(reply_id,user_id,emoji) values(p_reply_id,u,p_emoji); end if; select count(*) into n from reply_reactions where reply_id=p_reply_id and emoji=p_emoji; return jsonb_build_object('active',not a,'count',n); end $$;
create or replace function public.testagram_create_reply_quote(p_reply_id uuid,p_content text) returns jsonb language plpgsql security invoker set search_path=public as $$ declare u uuid:=auth.uid(); q uuid; begin if u is null then raise exception using errcode='42501',message='Authentication required'; end if; if not exists(select 1 from replies where id=p_reply_id) then raise exception using errcode='22023',message='Reply not found'; end if; insert into reply_quotes(reply_id,user_id,content) values(p_reply_id,u,coalesce(nullif(trim(p_content),''),'')) on conflict(reply_id,user_id) do update set content=excluded.content returning id into q; return jsonb_build_object('id',q); end $$;
create or replace function public.testagram_reply_engagement(p_reply_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare u uuid:=auth.uid(); begin return jsonb_build_object('likes',(select count(*) from reply_likes where reply_id=p_reply_id),'reposts',(select count(*) from reply_reposts where reply_id=p_reply_id),'bookmarks',(select count(*) from reply_bookmarks where reply_id=p_reply_id),'shares',(select count(*) from reply_shares where reply_id=p_reply_id),'replies',(select count(*) from replies where parent_reply_id=p_reply_id),'quotes',(select count(*) from reply_quotes where reply_id=p_reply_id),'reaction_total',(select count(*) from reply_reactions where reply_id=p_reply_id),'is_liked',exists(select 1 from reply_likes where reply_id=p_reply_id and user_id=u),'is_reposted',exists(select 1 from reply_reposts where reply_id=p_reply_id and user_id=u),'is_bookmarked',exists(select 1 from reply_bookmarks where reply_id=p_reply_id and user_id=u),'user_reactions',coalesce((select jsonb_agg(emoji order by created_at) from reply_reactions where reply_id=p_reply_id and user_id=u),'[]'::jsonb)); end $$;
grant execute on function public.testagram_toggle_reply_reaction(uuid,text),public.testagram_create_reply_quote(uuid,text) to authenticated;